package com.termux.app.workspace;
import android.app.Application;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiToolProbeTest {
 static class Fake implements LocalAiToolProbe.Model{String schemas="ORIGINAL",scope="original";boolean thinking=true,greedy=true;int calls;AtomicBoolean cancel;boolean fail;
 public String schemas(){return schemas;}public void schemas(String s){schemas=s;}public String scope(){return scope;}public void scope(String s){scope=s;}public boolean thinking(){return thinking;}public void thinking(boolean v){thinking=v;}public boolean greedy(){return greedy;}public void greedy(boolean v){greedy=v;}
 public String infer(JSONArray messages,String system,int tokens)throws Exception{int i=calls++;assertEquals(1,messages.length());assertEquals(512,tokens);assertNotEquals("original",scope);if(cancel!=null){cancel.set(true);throw new java.util.concurrent.CancellationException();}if(fail)throw new IllegalStateException("test engine error");if(i==0){assertEquals(0,new JSONArray(schemas).length());return "ROLE_OK";}assertEquals(i==4,thinking);assertEquals(i==3,greedy);return new JSONObject().put("tool","write").put("path","/root/project/tool-probe-guide.txt").put("text","1. Check Python\n2. Install if needed\n3. Verify").toString();}
 }
 WorkspaceStore.Session profile(){WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="write";p.localProject="/root/project";return p;}
 void restored(Fake f){assertEquals("ORIGINAL",f.schemas);assertEquals("original",f.scope);assertTrue(f.thinking);assertTrue(f.greedy);}
 @Test public void capturesChoicesWithoutExecutingOrChangingSettings()throws Exception{Fake f=new Fake();LocalAiToolProbe p=new LocalAiToolProbe();WorkspaceStore.Session profile=profile();p.run(profile,LocalAiLiteRt.schemas(profile),f,new AtomicBoolean(),()->{});assertEquals(5,f.calls);assertEquals("completed",p.phase);restored(f);assertEquals("marker_match",p.results.getJSONObject(0).getString("observed"));for(int i=1;i<5;i++){assertFalse(p.results.getJSONObject(i).getBoolean("toolExecutionEnabled"));assertEquals("write_requested",p.results.getJSONObject(i).getString("observed"));}assertTrue(p.report(true).contains("НЕ выполняются"));}
 @Test public void inferenceFailureAndCancellationRestoreAllOverrides()throws Exception{Fake f=new Fake();f.fail=true;LocalAiToolProbe p=new LocalAiToolProbe();p.run(profile(),LocalAiLiteRt.schemas(profile()),f,new AtomicBoolean(),()->{});assertEquals(5,f.calls);assertEquals("error",p.results.getJSONObject(0).getString("observed"));restored(f);f=new Fake();AtomicBoolean cancelled=new AtomicBoolean();f.cancel=cancelled;try{p.run(profile(),LocalAiLiteRt.schemas(profile()),f,cancelled,()->{});fail();}catch(java.util.concurrent.CancellationException expected){}restored(f);assertFalse(p.running);assertEquals("stopped",p.phase);}
 @Test public void readOnlySessionCannotEnterWriteProbe()throws Exception{WorkspaceStore.Session profile=profile();profile.localAccess="read";Fake f=new Fake();try{new LocalAiToolProbe().run(profile,LocalAiLiteRt.schemas(profile),f,new AtomicBoolean(),()->{});fail();}catch(IllegalArgumentException expected){}assertEquals(0,f.calls);restored(f);}
}
